def count_keywords(lines: List[str]) -> Dict[str, int]:
    counts = {'import': 0, 'def': 0, 'class': 0}
    for line in lines:
        for keyword in ['import', 'def', 'class']:
            if keyword in line:
                counts[keyword] += 1
    return counts

