from urllib.parse import urlparse

def validate_url(url: str) -> bool:
    parsed_url = urlparse(url)

    # Check if the scheme is valid
    valid_schemes = {'http', 'https', 'ftp', 'ftps'}
    if parsed_url.scheme not in valid_schemes:
        return False

    # Validate the domain
    domain = parsed_url.netloc
    if not domain:
        return False

    # Split domain into subdomains and main domain with TLD
    parts = domain.split('.')
    if len(parts) < 2:
        return False

    # Check for invalid characters in domain parts
    for part in parts:
        if not part.isalnum() and not (part[0] == '-' and part[1:].isalnum()):
            return False

    # Check TLD length
    tld = parts[-1]
    if len(tld) < 2:
        return False

    # Check for invalid subdomains (e.g., starting or ending with '-')
    for i, part in enumerate(parts):
        if i == 0 and part.startswith('-'):
            return False
        if i == len(parts) - 1 and part.endswith('-'):
            return False

    # Validate optional parts
    path = parsed_url.path
    query = parsed_url.query
    fragment = parsed_url.fragment

    # Path must be a valid string (optional)
    if path and not path.isalnum() and not (path[0] == '-' and path[1:].isalnum()):
        return False

    # Query must be valid key-value pairs (optional)
    if query:
        pairs = query.split('&')
        for pair in pairs:
            if '=' not in pair:
                return False
            key, value = pair.split('=', 1)
            if not key.isalnum() and not (key[0] == '-' and key[1:].isalnum()):
                return False
            if not value.isalnum() and not (value[0] == '-' and value[1:].isalnum()):
                return False

    # Fragment must start with '#' (optional)
    if fragment and not fragment.startswith('#'):
        return False

    return True

