def handle_pid_redirect(source_pid, destination_pid):
    source_type = source_pid['pid_type']
    destination_type = destination_pid['pid_type']

    if source_type == destination_type:
        return {
            'status': 301,
            'message': 'Moved Permanently.',
            'location': f'/records/{destination_pid["pid_value"]}'
        }
    else:
        return {
            'status': 400,
            'message': 'PID types do not match.'
        }

def countVisibleBuildings(heights: List[int]) -> int:
    if not heights:
        return 0
    max_height = heights[0]
    count = 1
    for height in heights[1:]:
        if height > max_height:
            count += 1
            max_height = height
    return count

from typing import List, Tuple, Dict

def build_graph(nodes: List[Tuple[str, Dict]], edges: List[Tuple[str, str, Dict]]) -> Dict:
    graph = {}
    for node in nodes:
        graph[node[0]] = []
    for edge in edges:
        source, dest, attrs = edge
        if source in graph:
            graph[source].append((dest, attrs))
    return graph

